'use strict';
const portraitInput=document.querySelector('#portrait');
const portraitUpload=portraitInput.closest('label');
const profilePhotoSection=document.createElement('section');profilePhotoSection.className='profile-photo-section';profilePhotoSection.setAttribute('aria-labelledby','profile-photo-heading');profilePhotoSection.innerHTML='<p class="eyebrow">THE PERSON BEHIND THE WORK</p><h4 id="profile-photo-heading">Your profile photo</h4><p class="hint">Add a photo of yourself. It appears in your living portfolio and classic resume.</p>';
form.elements.role.closest('label').after(profilePhotoSection);
portraitUpload.firstChild.textContent='Add / replace your photo ';
portraitInput.setAttribute('aria-label','Add your profile photo');
profilePhotoSection.append(portraitUpload,document.querySelector('#remove-portrait'));
const portraitPreview=document.createElement('div');portraitPreview.className='portrait-upload-preview';portraitUpload.before(portraitPreview);
const portraitStatus=document.createElement('p');portraitStatus.id='portrait-status';portraitStatus.className='portrait-status';portraitStatus.setAttribute('role','status');portraitStatus.setAttribute('aria-live','polite');portraitUpload.after(portraitStatus);portraitInput.setAttribute('aria-describedby','portrait-status');
function updatePortraitThumbnail(){portraitPreview.innerHTML=`<img src="${escapeHTML(hasPersonalPortrait()?state.portrait:professionImage(state.role))}" alt="${hasPersonalPortrait()?'Your profile photo':'Example photo placeholder'}"><div><b>${hasPersonalPortrait()?'Your profile photo':'Your photo goes here'}</b><p>${hasPersonalPortrait()?'Shown beside your name in your portfolio and resume.':'Example image from this profession’s card. Upload your own photo to replace it.'}</p></div>`;document.querySelector('#remove-portrait').hidden=!hasPersonalPortrait();}
const portraitBaseRender=render;render=function(){portraitBaseRender();updatePortraitThumbnail();};
portraitInput.onchange=async event=>{const file=event.target.files[0];if(!file)return;if(!draftsReady||mediaBusy||storageBusy){portraitStatus.textContent='Please wait for your draft to finish loading, saving or uploading, then choose your photo again.';event.target.value='';return;}mediaBusy=true;portraitInput.disabled=true;document.querySelector('#save').disabled=true;document.querySelector('#reset').disabled=true;portraitStatus.textContent='Preparing your portrait…';try{const nextPortrait=await readImage(file);state.portrait=nextPortrait;revision++;dirty();portraitStatus.textContent='Portrait updated in your portfolio and resume. Save on this device to keep it.';feedback.textContent='Portrait updated in both previews.';}catch(error){portraitStatus.textContent=error.message;feedback.textContent=error.message;}finally{mediaBusy=false;portraitInput.disabled=false;document.querySelector('#save').disabled=false;document.querySelector('#reset').disabled=false;event.target.value='';}};
document.querySelector('#remove-portrait').onclick=()=>{if(mediaBusy||storageBusy)return;state.portrait='';revision++;dirty();portraitStatus.textContent='Portrait removed. You can choose another photo.';};
updatePortraitThumbnail();
